mapper.select:
SELECT id, client_id AS clientId, redirect_uri AS redirectUri, created_at AS createdAt
FROM public.identity_client_redirect_uri
WHERE client_id = #{clientId}
ORDER BY id
LIMIT #{limit}

mapper.update:
UPDATE tianquan_oauth.oauth_client
SET version = #{version}, create_time = #{createdAt}, update_time = #{updatedAt}
WHERE tenant_id = #{partitionId} AND client_id = #{clientId} AND deleted_at IS NULL

UPDATE tianquan_oauth.oauth_resource
SET version = #{version}, create_time = #{createdAt}, update_time = #{updatedAt}
WHERE tenant_id = #{partitionId} AND resource_server_id = #{resourceServerId} AND deleted_at IS NULL

UPDATE tianquan_oauth.oauth_grant
SET version = #{version}, create_time = #{createdAt}, update_time = #{updatedAt}
WHERE tenant_id = #{partitionId} AND client_pk = #{clientPk}
  AND resource_server_id = #{resourceServerId} AND grant_type = #{grantType} AND deleted_at IS NULL
